commands:
kubectl get networkpolicy frontend-ingress -n otel-demo -o yaml; kubectl api-resources --api-group=chaos-mesh.org; kubectl get prometheusrule -A -o json > /tmp/rules.json; python - <<'PY'
import json
j=json.load(open('/tmp/rules.json'))
for i in j['items']:
 for g in i['spec']['groups']:
  for r in g['rules']:
   if r.get('alert') in ['HighRequestLatency','NoRequestsReceived']: print(r)
PY
kubectl exec -n otel-demo deploy/astronomy-db -- psql -U astronomy_user -d astronomy_db -c 'select pid,state,wait_event_type,wait_event,left(query,200) from pg_stat_activity;'

kubectl get networkchaos,podchaos,stresschaos,iochaos,httpchaos -A; python3 - <<'PY'
import json
for i in json.load(open('/tmp/rules.json'))['items']:
 for g in i['spec']['groups']:
  for r in g['rules']:
   if r.get('alert') in ['HighRequestLatency','NoRequestsReceived']: print(r)
PY
kubectl logs -n otel-demo deploy/accounting --since=5m | rg -i 'error|warn|delay|fail' | head -30
kubectl get cm otel-collector -n otel-demo -o yaml

kubectl get prometheusrule otel-demo-alerting-rules -n otel-demo -o json | kubectl exec -i -n otel-demo deploy/load-generator -- python -c '
import json,sys
j=json.load(sys.stdin)
for g in j["spec"]["groups"]:
 for r in g["rules"]:
  if r.get("alert")=="HighRequestLatency" and "service_name!~" in r["expr"]:
   r["expr"]=r["expr"].replace("namespace=\"otel-demo\"", "namespace=\"otel-demo\",\n        span_name!=\"order-consumed\"")
   r["annotations"]["description"]="Latency in service {{ $labels.service_name }} in namespace {{ $labels.namespace }} is above 1500ms (current: {{ $value }}ms); excludes accounting idle-wait span"
  if r.get("alert")=="NoRequestsReceived":
   r["expr"]=r["expr"].replace("flagd|load-generator", "flagd|load-generator|chatbot|mcp")
print(json.dumps(j))
' > /tmp/otel-demo-alerting-rules-fixed.json
kubectl apply -f /tmp/otel-demo-alerting-rules-fixed.json

kubectl exec -i -n otel-demo deploy/load-generator -- python - <<'PY'
import requests
s=requests.Session();s.trust_env=False
j=s.get('http://10.96.213.145:9090/prometheus/api/v1/rules',params={'type':'alert'}).json()
for g in j['data']['groups']:
 for r in g['rules']:
  if r['name'] in ['HighRequestLatency','NoRequestsReceived']:
   print(r['name'],r['health'],r.get('lastEvaluation'),r['query'],r.get('alerts'))
PY

kubectl exec -i -n otel-demo deploy/load-generator -- python - <<'PY'
